// === PREPARER SORTIE TELEGRAM ===
const item = $input.item.json;
const output = String(item.output || '').trim();
const steps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];

// 1) chatId TOUJOURS depuis Telegram Trigger
let chatId = '';
try {
  const msg = $('Telegram Trigger').item.json.message;
  if (msg && msg.chat && msg.chat.id != null) {
    chatId = String(msg.chat.id);
  }
} catch(e) {}

// 2) Chercher URL image dans les outputs des outils (intermediateSteps)
let imageUrl = '';
for (const step of steps) {
  const obs = step.observation;
  if (!obs) continue;
  const obsStr = typeof obs === 'string' ? obs : JSON.stringify(obs);
  const m = obsStr.match(/https:\/\/oaidalleapiprodscus\.blob\.core\.windows\.net\/[^\s"'\)\]\\]+/);
  if (m) { imageUrl = m[0]; break; }
}

// 3) Fallback: chercher URL dans la réponse texte de l'agent
if (!imageUrl && output) {
  const m1 = output.match(/https:\/\/oaidalleapiprodscus\.blob\.core\.windows\.net\/[^\s<>"'\)\]]+/i);
  if (m1) imageUrl = m1[0];
  else {
    const m2 = output.match(/https?:\/\/[^\s<>"'\)\]]+\.(?:png|jpg|jpeg|gif|webp)(?:[?#][^\s<>"'\)\]]*)?/i);
    if (m2) imageUrl = m2[0];
  }
}

// 4) Légende (texte de l'agent SANS l'URL)
let caption = output;
if (imageUrl) {
  caption = output.split(imageUrl).join('').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}
if (!caption) caption = '\uD83C\uDFA8';
if (caption.length > 1024) caption = caption.substring(0, 1021) + '...';

// 5) Texte final (jamais vide, max 4096)
let text = output;
if (!text) text = 'D\u00e9sol\u00e9, aucune r\u00e9ponse g\u00e9n\u00e9r\u00e9e.';
if (text.length > 4096) text = text.substring(0, 4093) + '...';

return [{ json: { chatId, imageUrl, text, caption } }];
